/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_products_after_update` AFTER UPDATE ON `tb_products` FOR EACH ROW BEGIN
    -- Compara únicamente las columnas reales de la tabla de forma segura contra NULL
    IF NOT (OLD.SKU <=> NEW.SKU) OR NOT (OLD.name <=> NEW.name) THEN
        INSERT INTO tb_logs (
            table_name,
            operation,
            db_user,
            operation_date,
            description,
            operation_status
        )
        VALUES (
            'tb_products',
            'Update',
            USER(),
            CURRENT_TIMESTAMP,
            CONCAT(
                'Producto actualizado. ID=', NEW.ID,
                ' | Cambios: ',
                IF(NOT (OLD.SKU <=> NEW.SKU), CONCAT('[SKU: ', COALESCE(OLD.SKU, 'NULL'), ' -> ', COALESCE(NEW.SKU, 'NULL'), '] '), ''),
                IF(NOT (OLD.name <=> NEW.name), CONCAT('[Nombre: ', COALESCE(OLD.name, 'NULL'), ' -> ', COALESCE(NEW.name, 'NULL'), '] '), '')
            ),
            b'1'
        );
    END IF;
END */;;
DELIMITER ;
